// Mirrors crates/ekko-core (settings.rs, notch.rs). Will be generated by tauri-specta in F2.

import { DEFAULT_APPEARANCE, type AppearanceSettings } from './appearanceTypes'
import type { NowPlaying, VolumeBackend } from './mediaTypes'
import type { IntegrationsBackend } from './integrations'
import {
  DEFAULT_GENERAL,
  DEFAULT_SHORTCUT_SETTINGS,
  type GeneralBackend,
  type GeneralSettings,
  type ShortcutSettings,
} from './generalTypes'
import type { ProductivityBackend } from './productivityTypes'
import type { ClipboardBackend } from './clipboardTypes'
import type { ShelfBackend } from './shelfTypes'
import type { CaptureBackend } from './captureTypes'
import type { UpdateBackend } from './updateTypes'
import type { ColorBackend } from './colorTypes'
import type { HudBackend } from './hudTypes'
import type { SystemBackend } from './systemTypes'

export * from './appearanceTypes'
export * from './mediaTypes'
export * from './integrations'
export * from './generalTypes'
export * from './productivityTypes'
export * from './systemTypes'
export * from './clipboardTypes'
export * from './shelfTypes'
export * from './captureTypes'
export * from './updateTypes'
export * from './colorTypes'
export * from './hudTypes'

export type DisplayMode = 'notch' | 'tray' | 'orb' | 'dock' | 'hub' | 'voice-only'
export type Persona = 'ekko' | 'ultron' | 'tobby'
export type DockSide = 'left' | 'right'
export type NotchSize = 'compact' | 'normal' | 'large'
export type NotchOpen = 'hover' | 'click'
export type NotchIdle = 'pill' | 'minimal'

export interface NotchSettings {
  /** Horizontal center as a fraction of the monitor width (0.5 = centered). */
  offset: number
  size: NotchSize
  openOn: NotchOpen
  hoverDelayMs: number
  idle: NotchIdle
  /** Grow animation from pill to panel, 0..1000 ms. */
  openMs: number
  /** Quick alerts (volume, brightness, battery…) in the pill, 1..10 s. */
  alertSeconds: number
}

export const DEFAULT_NOTCH: NotchSettings = {
  offset: 0.5,
  size: 'normal',
  openOn: 'hover',
  hoverDelayMs: 180,
  idle: 'pill',
  openMs: 300,
  alertSeconds: 5,
}

export interface MonitorInfo {
  index: number
  name: string
  width: number
  height: number
  primary: boolean
}

export interface Settings {
  version: number
  userName: string
  assistantName: string
  displayMode: DisplayMode
  persona: Persona
  dockSide: DockSide
  monitor: number
  orbPosition: [number, number] | null
  notch: NotchSettings
  appearance: AppearanceSettings
  /** False until the welcome flow is finished. */
  onboarded: boolean
  /** Autostart, hide in fullscreen, quiet hours, sound. */
  general: GeneralSettings
  /** Global shortcuts (canonical combos). */
  shortcuts: ShortcutSettings
}

export const DEFAULT_SETTINGS: Settings = {
  version: 1,
  userName: '',
  assistantName: 'Ekko',
  displayMode: 'notch',
  persona: 'ekko',
  dockSide: 'right',
  monitor: 0,
  orbPosition: null,
  notch: DEFAULT_NOTCH,
  appearance: DEFAULT_APPEARANCE,
  onboarded: false,
  general: DEFAULT_GENERAL,
  shortcuts: DEFAULT_SHORTCUT_SETTINGS,
}

/** Overlay area that must receive the mouse, logical px relative to the window. */
export interface HitRect {
  x: number
  y: number
  w: number
  h: number
  /** Increasing counter so the backend can drop out-of-order updates. */
  seq?: number
}

// Mirrors crates/ekko-core (timers.rs, pomodoro.rs).
export interface TimerInfo {
  id: string
  label: string
  totalMs: number
  /** Epoch ms; meaningless while paused. */
  endsAtMs: number
  /** Ms left while paused, null while running. */
  pausedLeftMs: number | null
}

export type PomodoroPhase = 'focus' | 'break'
export type PomodoroAction = 'start' | 'pause' | 'skip' | 'reset'

export interface PomodoroInfo {
  phase: PomodoroPhase
  endsAtMs: number | null
  pausedLeftMs: number | null
  /** Finished focus blocks. */
  cycles: number
  focusMin: number
  breakMin: number
  autoAdvance: boolean
}

export interface TimersSnapshot {
  timers: TimerInfo[]
  pomodoro: PomodoroInfo
}

export type Unlisten = () => void

/** Everything the UI may ask from the backend. Real (Tauri) or mock (browser/prototype). */
export interface Backend
  extends
    IntegrationsBackend,
    VolumeBackend,
    ProductivityBackend,
    GeneralBackend,
    SystemBackend,
    ClipboardBackend,
    ShelfBackend,
    CaptureBackend,
    UpdateBackend,
    ColorBackend,
    HudBackend {
  readonly kind: 'tauri' | 'mock'
  getSettings(): Promise<Settings>
  onSettingsChanged(cb: (s: Settings) => void): Promise<Unlisten>
  setDisplayMode(mode: DisplayMode): Promise<void>
  setPersona(persona: Persona): Promise<void>
  setDockSide(side: DockSide): Promise<void>
  setNames(userName: string, assistantName: string): Promise<void>
  openSettings(): Promise<void>
  summon(): Promise<void>
  showPanelBesideOrb(): Promise<void>
  /** Overlay windows (notch, dock) report their visible part for click-through. */
  setHitRect(rect: HitRect): Promise<void>
  onHover(cb: (inside: boolean) => void): Promise<Unlisten>
  onSummon(cb: () => void): Promise<Unlisten>
  /** Cross-window broadcast (mock assistant state lives in every window). */
  broadcast<T>(event: string, payload: T): Promise<void>
  listen<T>(event: string, cb: (payload: T) => void): Promise<Unlisten>
  setNotch(notch: NotchSettings): Promise<void>
  /** Look on top of the persona; sanitized and broadcast by the backend. */
  setAppearance(appearance: AppearanceSettings): Promise<void>
  listMonitors(): Promise<MonitorInfo[]>
  setMonitor(index: number): Promise<void>
  /** Notch drag along the top edge. `dx` (CSS px since start) is used by the mock only;
   * Tauri follows the real cursor. */
  notchDrag(phase: 'start' | 'move' | 'end', dx: number): Promise<void>
  /** Pill center inside the notch window (logical px); null until placed. */
  getNotchAnchor(): Promise<number | null>
  onNotchAnchor(cb: (anchor: number) => void): Promise<Unlisten>
  onFocusChanged(cb: (focused: boolean) => void): Promise<Unlisten>
  focusSelf(): Promise<void>
  togglePalette(): Promise<void>
  onPaletteOpen(cb: () => void): Promise<Unlisten>
  openOnboarding(): Promise<void>
  finishOnboarding(): Promise<void>
  /** Opens the on-screen alarm window with any JSON alarm object. */
  showAlarm<T>(alarm: T): Promise<void>
  /** The alarm the alarm window was opened for (null if already taken). */
  takeAlarm<T>(): Promise<T | null>
  onAlarm<T>(cb: (alarm: T) => void): Promise<Unlisten>
  hideSelf(): Promise<void>
  startDragging(): Promise<void>
  /** Timers live in the backend; every call returns the new snapshot. */
  listTimers(): Promise<TimersSnapshot>
  onTimersChanged(cb: (snapshot: TimersSnapshot) => void): Promise<Unlisten>
  timerAdd(label: string, seconds: number): Promise<TimersSnapshot>
  timerPause(id: string): Promise<TimersSnapshot>
  timerResume(id: string): Promise<TimersSnapshot>
  timerCancel(id: string): Promise<TimersSnapshot>
  timerExtend(id: string, seconds: number): Promise<TimersSnapshot>
  pomodoro(action: PomodoroAction): Promise<TimersSnapshot>
  /** What Windows reports as playing (any player); null when nothing is. */
  mediaNow(): Promise<NowPlaying | null>
  onMediaChanged(cb: (now: NowPlaying | null) => void): Promise<Unlisten>
  mediaPlayPause(): Promise<void>
  mediaNext(): Promise<void>
  mediaPrevious(): Promise<void>
  /** Seek the OS player (only when `NowPlaying.canSeek`). */
  mediaSeek(positionMs: number): Promise<void>
}
